#include "helpers/DirectionalLightHelper.h"
namespace{thread_local Vector3 v1,v2,v3;}
DirectionalLightHelper::DirectionalLightHelper(std::shared_ptr<DirectionalLight> light,double size,HelperColor color):light(std::move(light)),color(std::move(color.value)){if(!this->light)throw JSTypeError("Cannot read properties of undefined (reading 'matrixWorld')");matrix.aliasTo(std::shared_ptr<Matrix4>(this->light,&this->light->matrixWorld),this->light);matrixAutoUpdate=false;type="DirectionalLightHelper";auto geometry=Helper_detail::geometry({-size,size,0,size,size,0,size,-size,0,-size,-size,0,-size,size,0});auto material=Helper_detail::lineMaterial();material->fog=false;lightPlane=std::make_shared<Line>(geometry,material);add(lightPlane);geometry=Helper_detail::geometry({0,0,0,0,0,1});targetLine=std::make_shared<Line>(geometry,material);add(targetLine);update();}
void DirectionalLightHelper::update(){matrixWorldNeedsUpdate=true;if(!light)throw JSTypeError("light is undefined");{const auto retained=light;retained->updateWorldMatrix(true,false);}{const auto target=light->target;if(!target)throw JSTypeError("light.target is undefined");target->updateWorldMatrix(true,false);}v1.setFromMatrixPosition(light->matrixWorld);v2.setFromMatrixPosition(light->target->matrixWorld);v3.subVectors(v2,v1);lightPlane->lookAt(v2);if(!color.isUndefined()){Helper_detail::setLineColor(lightPlane->material,color);Helper_detail::setLineColor(targetLine->material,color);}else{Helper_detail::lineColor(lightPlane->material).copy(light->color);Helper_detail::lineColor(targetLine->material).copy(light->color);}targetLine->lookAt(v2);targetLine->scale.z=v3.length();}
std::shared_ptr<Object3D> DirectionalLightHelper::clone(bool)const{return std::make_shared<DirectionalLightHelper>(nullptr);}
void DirectionalLightHelper::dispose(){Object3D::dispose();Helper_detail::disposeGeometry(lightPlane->geometry);Helper_detail::disposeMaterial(lightPlane->material);Helper_detail::disposeGeometry(targetLine->geometry);Helper_detail::disposeMaterial(targetLine->material);}
